package com.collabspace.controller; import com.collabspace.dto.NotificationDtos.NotificationResponse;import com.collabspace.entity.Notification;import com.collabspace.repository.NotificationRepository;import com.collabspace.service.CurrentUserService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor public class NotificationController {private final NotificationRepository repo;private final CurrentUserService current; @GetMapping public Page<NotificationResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){return repo.findByUserIdOrderByCreatedAtDesc(current.get().getId(),PageRequest.of(page,size)).map(this::dto);} @GetMapping("/unread-count") public long unread(){return repo.countByUserIdAndReadFalse(current.get().getId());}@PutMapping("/{id}/read") public void read(@PathVariable UUID id){Notification n=repo.findById(id).orElseThrow();if(!n.getUser().getId().equals(current.get().getId()))throw new SecurityException("Forbidden");n.setRead(true);repo.save(n);} private NotificationResponse dto(Notification n){return new NotificationResponse(n.getId(),n.getType().name(),n.getMessage(),n.isRead(),n.getCreatedAt());}}